const PaymentPending = () => {
  return (
    <div style={{ textAlign: "center", marginTop: "100px" }}>
      <h2>Payment Under Verification ⏳</h2>
      <p>We are checking your payment.</p>
      <p>Please wait for admin approval.</p>
    </div>
  );
};

export default PaymentPending;
